def mode_value(xs):
    """
    Return the most common element of a non-empty list `xs`.
    On a tie, return the element that appears first in the list.
    """
    if not xs:
        raise ValueError("mode_value requires a non-empty list")

    counts = {}
    first_index = {}

    for idx, value in enumerate(xs):
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1
            first_index[value] = idx

    best_value = None
    best_count = -1
    best_first = len(xs)

    for value, count in counts.items():
        idx = first_index[value]
        if count > best_count or (count == best_count and idx < best_first):
            best_value = value
            best_count = count
            best_first = idx

    return best_value
